Definition put_setup_stmt (pc callee ret : Z) : Prop :=
  forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem) (E p0 P n p1 : Z),
  evt rsegs (fun ms' => ms' = put_ms callee (wz ret) sp gp tp t0 t1 t2 E p0 (wz P) (Z_to_bv 64 (bv_unsigned sp + -112)) (wz n) (wz E) a4 a5 a6 a7 P (wz n) p1 t3 t4 t5 t6 F fc m)
    (put_ms pc rax sp gp tp t0 t1 t2 E p0 a0 a1 a2 a3 a4 a5 a6 a7 P (wz n) p1 t3 t4 t5 t6 F fc m).

Local Ltac setup_script :=
  intros rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc m E p0 P n p1;
  unfold put_ms, PUT_JT, P_BP_PARSE_START_LINE, P_BP_PARSE_FIELDS, P_BP_PARSE_BODY, P_BP_PARSE_CHUNK_HEADER; unfold wz;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  do 5 step; apply evt_done; reflexivity.

