(* [comment removed for export] *)
Definition put_arm9b_stmt : Prop :=
  forall rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3x t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P E : Z) (c : pcore) (pad7 pad2 j8 : list byte) (tmp : list cell) (p p0 p1 r : Z),
  put_frame m sp j8 tmp p ->
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> 0 <= p -> 0 <= r <= pc_len c -> p + r < 2^64 -> mem_inv rsegs m ->
  evt rsegs (fun ms' => exists m' a1' a2',
        ms' = put_ms PUT_COMMON rax sp gp tp t0 t1 t2 E p0 (wz r) a1' a2' a3 a4 a5 a6 a7 P s3x p1 t3 t4 t5 t6 F fc m'
        /\ munch [(bv_unsigned sp + -112, bv_unsigned sp + -104); (P, P + 80)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
        /\ put_frame m' sp j8 tmp (p + r)
        /\ rw_cells rsegs m' P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c - r) (pc_len0 c) (pc_skip c) (pc_hlim c)
                                                     (if pc_len c =? r then 8 else pc_state c) (pc_f c)) pad7 pad2))
    (put_ms 0x39728 rax sp gp tp t0 t1 t2 E p0 (wz r) a1 a2 a3 a4 a5 a6 a7 P s3x p1 t3 t4 t5 t6 F fc m).

